CREATE TABLE gold.usage_charges_by_category (`account_id` FixedString(64) CODEC(ZSTD(1)), `billing_month` Date CODEC(ZSTD(1)), `category` LowCardinality(String) CODEC(ZSTD(1)), `show_name` LowCardinality(String) CODEC(ZSTD(1)), `metric` LowCardinality(String) CODEC(ZSTD(1)), `quantity` Decimal(18, 3) CODEC(ZSTD(1)), `unit_price_usd` Decimal(18, 6) CODEC(ZSTD(1)), `charge_usd` Decimal(18, 6) CODEC(ZSTD(1)), `updated_at` DateTime64(3) DEFAULT now64(3) CODEC(ZSTD(1))) ENGINE = SharedSummingMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}', charge_usd) PARTITION BY toYYYYMM(billing_month) ORDER BY (account_id, billing_month, category, metric) SETTINGS index_granularity = 8192